# Distance from boundary
def manhattan_distance_from_frame(r, c, interior_min_r, interior_max_r, interior_min_c, interior_max_c):
    """Manhattan distance to the nearest boundary of the interior"""
    # If we're at a corner or edge of the interior, distance is minimum side offset
    if r == interior_min_r and c == interior_min_c:
        return 0
    if r == interior_min_r and c == interior_max_c:
        return 0
    if r == interior_max_r and c == interior_min_c:
        return 0
    if r == interior_max_r and c == interior_max_c:
        return 0

    # If we're on an edge but not corner
    if r == interior_min_r:
        return min(abs(c - interior_min_c), abs(c - interior_max_c))
    if r == interior_max_r:
        return min(abs(c - interior_min_c), abs(c - interior_max_c))
    if c == interior_min_c:
        return min(abs(r - interior_min_r), abs(r - interior_max_r))
    if c == interior_max_c:
        return min(abs(r - interior_min_r), abs(r - interior_max_r))

    # Interior cell
    return min(
        abs(r - interior_min_r),
        abs(r - interior_max_r),
        abs(c - interior_min_c),
        abs(c - interior_max_c)
    )

