def apply_transformation_v3(g):
    rows, cols = len(g), len(g[0])
    output = [row[:] for row in g]

    visited = [[False]*cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if g[r][c] == 1 and not visited[r][c]:
                queue = [(r, c)]
                visited[r][c] = True
                while queue:
                    cr, cc = queue.pop(0)
                    comp_positions = [(cr, cc)]
                    for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if g[nr][nc] == 1 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))
                    components.append(comp_positions)

    for indices in components:
        min_r = min(p[0] for p in indices)
        max_r = max(p[0] for p in indices)
        min_c = min(p[1] for p in indices)
        max_c = max(p[1] for p in indices)

        inter_rmin, inter_rmax = min_r + 1, max_r - 1
        inter_cmin, inter_cmax = min_c + 1, max_c - 1
        interior_valid = inter_rmin <= inter_rmax and inter_cmin <= inter_cmax

        center_r = inter_rmin + (inter_rmax - inter_rmin + 1) // 2 if interior_valid else 0
        center_c = inter_cmin + (inter_cmax - inter_cmin + 1) // 2 if interior_valid else 0

        # New frame bounds
        new_rmin, new_rmax = max(0, min_r - 1), min(rows - 1, max_r + 1)
        new_cmin, new_cmax = max(0, min_c - 1), min(cols - 1, max_c + 1)

        # Add outer frame (2s) - but only on the TRUE boundary, skip cells already in interior
        for rr in range(new_rmin, new_rmax + 1):
            for cc in range(new_cmin, new_cmax + 1):
                # Only apply frame if on the boundary AND not already part of the interior region
                is_boundary = (rr == new_rmin or rr == new_rmax or cc == new_cmin or cc == new_cmax)
                is_interior = (inter_rmin <= rr <= inter_rmax and inter_cmin <= cc <= inter_cmax) and interior_valid
                if is_boundary and not is_interior and output[rr][cc] == 0:
